  Lemma cc_Jw : forall regs m (wd hd datas wpls datad wpld j : Z),
    (0 <= j < wd)%Z -> (wd < 2 ^ 31)%Z -> (32 <= hd < 2 ^ 31)%Z -> (0 <= wpls < 2 ^ 25)%Z -> (0 <= wpld < 2 ^ 25)%Z ->
    getr regs 11 = Z_to_bv 64 j -> getr regs 7 = Z_to_bv 64 wd -> getr regs 29 = Z_to_bv 64 hd -> getr regs 18 = Z_to_bv 64 wpls ->
    getr regs 10 = Z_to_bv 64 wpld -> getr regs 9 = Z_to_bv 64 datas -> getr regs 8 = Z_to_bv 64 datad -> getr regs 12 = Z_to_bv 64 hd ->
    getr regs 13 = Z_to_bv 64 32 ->
    exists regs',
      msteps SEGS (mkst regs (0x87b98 : word) m rom) (mkst regs' (0x87bd4 : word) m rom)
      /\ getr regs' 6 = Z_to_bv 64 (- j - 1) /\ getr regs' 7 = Z_to_bv 64 (datad + 4 * wpld * (hd - 1))
      /\ getr regs' 28 = Z_to_bv 64 (datas + 4 * wpls * (wd - 1 - j)) /\ getr regs' 29 = Z_to_bv 64 0
      /\ regs_agree (fun r => In r [6; 7; 28; 29; 30]%list) regs regs'.
