  (* [comment removed for export] *)
  Lemma cc_Kz : forall regs m (lines lined wpld k : Z) (bs : list byte) (v : word),
    rdn SEGS m (Z_to_bv 64 (lines + 4 * k)) 4 = Some bs -> bytes_le_to_Z bs = bv_unsigned v -> v_lw v = Z_to_bv 64 0 ->
    (0 <= k < 2 ^ 30)%Z ->
    getr regs 29 = Z_to_bv 64 k -> getr regs 28 = Z_to_bv 64 lines -> getr regs 7 = Z_to_bv 64 lined -> getr regs 15 = Z_to_bv 64 (- (128 * wpld)) ->
    exists regs',
      msteps SEGS (mkst regs (0x87bd4 : word) m rom) (mkst regs' (0x87bcc : word) m rom)
      /\ getr regs' 7 = Z_to_bv 64 (lined - 128 * wpld)
      /\ regs_agree (fun r => In r [7; 30]%list) regs regs'.
