  (* [comment removed for export] *)
  Lemma cc_M : forall (b : bool) regs m (s lined wd j mm : Z) (v : word) (bt : list byte) (vt : word),
    c_lts (v_sllw (v_lw v) (Z_to_bv 64 mm)) (Z_to_bv 64 0) = b ->
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= j < wd)%Z -> (wd < 2 ^ 31)%Z -> (0 <= lined + 4 * ((wd - 1 - j) / 32) < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 60)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 wd)) ->
    rdn SEGS m (Z_to_bv 64 (lined + 4 * ((wd - 1 - j) / 32))) 4 = Some bt -> bytes_le_to_Z bt = bv_unsigned vt ->
    store_ok SEGS m (Z_to_bv 64 (lined + 4 * ((wd - 1 - j) / 32))) 4 = true ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 30 = v_lw v -> getr regs 31 = Z_to_bv 64 mm -> getr regs 7 = Z_to_bv 64 lined ->
    getr regs 6 = Z_to_bv 64 (- j - 1) ->
    exists regs' m',
      msteps SEGS (mkst regs (0x87bf8 : word) m rom) (mkst regs' (0x87bec : word) m' rom)
      /\ (if b then exists wv : word, m' = wbytes m (Z_to_bv 64 (lined + 4 * ((wd - 1 - j) / 32))) (word_to_le_bytes 4 wv) else m' = m)
      /\ regs_agree (fun r => In r [19; 20; 21]%list) regs regs'.
Proof.
