  Lemma cc_Mx : forall regs m (mm lined wpld : Z), (mm + 1 = 32)%Z ->
    getr regs 31 = Z_to_bv 64 mm -> getr regs 7 = Z_to_bv 64 lined -> getr regs 14 = Z_to_bv 64 (- (4 * wpld)) -> getr regs 13 = Z_to_bv 64 32 ->
    exists regs',
      msteps SEGS (mkst regs (0x87bec : word) m rom) (mkst regs' (0x87bcc : word) m rom)
      /\ getr regs' 7 = Z_to_bv 64 (lined - 4 * wpld)
      /\ regs_agree (fun r => In r [7; 31]%list) regs regs'.
Proof.
