  (* [comment removed for export] *)
  Lemma cc_Kn : forall regs m (k nsw : Z), (0 <= k)%Z -> (k + 1 < nsw < 2 ^ 31)%Z ->
    getr regs 29 = Z_to_bv 64 k -> getr regs 16 = Z_to_bv 64 nsw ->
    exists regs',
      msteps SEGS (mkst regs (0x87bcc : word) m rom) (mkst regs' (0x87bd4 : word) m rom)
      /\ getr regs' 29 = Z_to_bv 64 (k + 1)
