  Lemma cc_Kx : forall regs m (s k nsw hd : Z), (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (k + 1 = nsw)%Z -> (0 <= nsw < 2 ^ 31)%Z -> (0 <= hd < 2 ^ 31)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 64)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 hd)) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 29 = Z_to_bv 64 k -> getr regs 16 = Z_to_bv 64 nsw ->
    exists regs',
      msteps SEGS (mkst regs (0x87bcc : word) m rom) (mkst regs' (0x87c2c : word) m rom)
      /\ getr regs' 29 = Z_to_bv 64 hd
      /\ regs_agree (fun r => In r [29]%list) regs regs'.
